static void skip_invariant(const SsSkip*s){unsigned count=0,eligible[6]={0};for(unsigned n=0;n<32;++n)if(s->nodes[n].live){++count;CHECK(s->nodes[n].height>=1&&s->nodes[n].height<=6);for(unsigned l=0;l<s->nodes[n].height;++l)++eligible[l];}CHECK(count==s->count);for(unsigned l=0;l<6;++l){unsigned at=s->head[l],seen=0;uint32_t last=0;while(at!=32){CHECK(at<32&&seen<32&&s->nodes[at].live&&s->nodes[at].height>l);if(seen)CHECK(last<s->nodes[at].key);last=s->nodes[at].key;++seen;at=s->nodes[at].next[l];}CHECK(seen==eligible[l]);}}
