 uint32_t state=0,out=77;CHECK(ss_random(&state,10,0,&out)==SS_EXHAUSTED&&state==0&&out==77);CHECK(ss_random(&state,10,1,&out)==SS_OK&&state==1013904223u&&out==3);for(unsigned n=0;n<2048;++n){uint32_t expected=0;for(unsigned j=0;j<n;++j)expected=expected*1664525u+1013904223u;CHECK(ss_random_advance(0,n)==expected);}CHECK(ss_random_advance(123,UINT32_MAX)==ss_random_advance(ss_random_advance(123,UINT32_MAX-9),9));
